  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "The inclusion criteria for the full-­ text review were: 1. Follow-­ up investigations (reinvestigation) prompted by incomplete procedures, poor bowel preparation, or any detected GI pathology in the terminal ileum or colon. 2. Any clinical indication for CCE. 3. Studies with more than 10 participants. 4. The FER did not need to be explicitly stated as the study's primary or secondary endpoint but could be calculated from the available raw data. Exclusion criteria primarily focused on studies where follow-­ up investigations were conducted for upper GI findings, as these conditions would not typically be identified during colonoscopy, the gold standard for comparison of CCE FERs. Additionally, studies where all participants underwent both colonoscopy and CCE as part of a diagnostic accuracy study were excluded (see figure 1).",
      "reason": "Eligibility components for follow-up requirements and eligible study designs are partially specified (e.g., follow-up reinvestigations and eligibility around FER calculation; exclusion rationale and some study-type information elsewhere), but the evidence does not clearly specify settings (and other question-framework components are not fully described)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_5",
      "quote": "There were no language restrictions, and all the non-­ English articles were screened with the intention of being translated and included if they met the predefined inclusion criteria.",
      "reason": "Language restriction is addressed, but dissemination year and publication/report status are only partially specified (e.g., publication date range and exclusion of grey/unpublished studies are stated in other evidence, but the element requires all report-characteristic eligibility criteria such as publication/report status comprehensively)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence distinguishes exclusions because outcomes were not measured from exclusions because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The evidence does not specify the groups used in each synthesis or link them to comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_5",
      "quote": "Conference abstracts were excluded due to their high risk of bias.",
      "reason": "A rationale is provided for at least one notable restriction (exclusion of conference abstracts due to high risk of bias), but rationales for other restrictions are not consistently provided in the retrieved evidence."
    }
  ],
  "confidence": 62
}

